using System.Collections.ObjectModel; using System.Windows; using AutoPecasERP.Core.Entities; using AutoPecasERP.Data.Context; using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Desktop.Views; public partial class PedidoCompraEditWindow:Window { readonly ObservableCollection<ItemPedidoCompra> itens=new(); public PedidoCompraEditWindow(){InitializeComponent();ItensGrid.ItemsSource=itens;Loaded+=async(_,__)=>{using var db=new ErpDbContext();FornecedorBox.ItemsSource=await db.Fornecedores.Where(x=>x.Ativo).OrderBy(x=>x.Empresa).ToListAsync();ProdutoBox.ItemsSource=await db.Produtos.OrderBy(x=>x.Descricao).ToListAsync();};} void Adicionar_Click(object s,RoutedEventArgs e){if(ProdutoBox.SelectedItem is not Produto p||!decimal.TryParse(QtdBox.Text,out var q)||!decimal.TryParse(CustoBox.Text,out var c)||q<=0||c<0)return;itens.Add(new ItemPedidoCompra{ProdutoId=p.Id,Produto=p,Quantidade=q,CustoUnitario=c});AtualizaTotal();} decimal Valor(string s)=>decimal.TryParse(s,out var v)?v:0; void AtualizaTotal()=>TotalText.Text=$"Total: {(itens.Sum(x=>x.Total)+Valor(FreteBox.Text)-Valor(DescontoBox.Text)):C}"; async void Salvar_Click(object s,RoutedEventArgs e){if(FornecedorBox.SelectedItem is not Fornecedor f||itens.Count==0){MessageBox.Show("Selecione fornecedor e adicione ao menos um produto.");return;}using var db=new ErpDbContext();var p=new PedidoCompra{Numero=$"PC{DateTime.Now:yyyyMMddHHmmss}",FornecedorId=f.Id,Frete=Valor(FreteBox.Text),Desconto=Valor(DescontoBox.Text),Status="Aguardando",Total=itens.Sum(x=>x.Total)+Valor(FreteBox.Text)-Valor(DescontoBox.Text)};foreach(var i in itens)p.Itens.Add(new ItemPedidoCompra{ProdutoId=i.ProdutoId,Quantidade=i.Quantidade,CustoUnitario=i.CustoUnitario});db.PedidosCompra.Add(p);db.Auditorias.Add(new Auditoria{Acao="Criação",Entidade="PedidoCompra",Referencia=p.Numero,Detalhes=$"Total {p.Total:N2}"});await db.SaveChangesAsync();DialogResult=true;} }